const commander = require('../');

// Default value of a flag/--no-flag pair must not depend on the order added.

describe('negated option default independent of order', () => {
  test.each([
    ['negated first', (p) => p.option('--no-pepper').option('--pepper')],
    ['positive first', (p) => p.option('--pepper').option('--no-pepper')],
  ])('no implicit default when both defined (%s)', (_, add) => {
    const program = add(new commander.Command());
    program.parse(['node', 'test']);
    expect('pepper' in program.opts()).toBe(false);
  });

  test('explicit default on negated option used when positive first', () => {
    const program = new commander.Command();
    program.option('--pepper').option('--no-pepper', 'remove pepper', 'plain');
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBe('plain');
  });

  test('explicit default on negated option used when negated first', () => {
    const program = new commander.Command();
    program.option('--no-pepper', 'remove pepper', 'plain').option('--pepper');
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBe('plain');
  });

  test('lone negated option defaults to true', () => {
    const program = new commander.Command();
    program.option('--no-pepper');
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBe(true);
  });
});
